        pairs: List<Pair<String, String>>,
        fillSentence: String,
        fillChoices: List<String>,
        fillCorrectIndex: Int,
        seq: List<String>? = null,
        isRevision: Boolean = false,
        isFinalAssessment: Boolean = false,
        sourceRef: String = SRC_HAFS
    ): LessonSpec = LessonSpec(
        title = title,
        arabic = arabic,
        pronunciation = pronunciation,
        objective = objective,
        explanation = explanation,
        keyRule = keyRule,
        wrongStatement = wrongStatement,
        rightStatement = rightStatement,
        mcqQuestion = mcqQuestion,
        mcqOptions = mcqOptions,
        mcqCorrectIndex = mcqCorrectIndex,
        pairs = pairs,
        fillSentence = fillSentence,
        fillChoices = fillChoices,
        fillCorrectIndex = fillCorrectIndex,
        sequenceCorrect = seq,
        sourceRef = if (isRevision || isFinalAssessment) SRC_NASHR else sourceRef,
        isRevision = isRevision,
        isFinalAssessment = isFinalAssessment
